/*
 * EncodingTool.c
 * ANSI C89 command-line encoding converter.
 * Codec tables are static; conversion does not use Windows charset APIs.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long U32;
typedef unsigned short U16;

#define ENC_OK 0
#define ENC_ERR_ARGUMENT 1
#define ENC_ERR_OPEN_INPUT 2
#define ENC_ERR_OPEN_OUTPUT 3
#define ENC_ERR_READ 4
#define ENC_ERR_WRITE 5
#define ENC_ERR_INVALID_UTF8 10
#define ENC_ERR_INVALID_UTF16 11
#define ENC_ERR_INVALID_CP949 12
#define ENC_ERR_UNREPRESENTABLE 13
#define ENC_ERR_CP437_REVERSE 14
#define ENC_ERR_USER_CANCEL 100
#define CHUNK_SIZE 32768UL
#define MAX_FILE_BYTES (128UL * 1024UL * 1024UL)

typedef struct {
    U16 code;
    U32 scalar;
} CP949Entry;

typedef struct {
    U32 scalar;
    U16 code;
} CP949ReverseEntry;

typedef struct {
    U32 *items;
    unsigned long count;
    unsigned long capacity;
} ScalarBuffer;

typedef struct {
    char error[40];
    char bytes[40];
    char action[16];
    unsigned long offset;
    U32 scalar;
    int has_scalar;
} Rule;

typedef struct {
    Rule *items;
    unsigned long count;
    unsigned long capacity;
} RuleList;

