static const unsigned long cp949_forward_count =
    (unsigned long)(sizeof(cp949_forward) / sizeof(cp949_forward[0]));
static const unsigned long cp949_reverse_count =
    (unsigned long)(sizeof(cp949_reverse) / sizeof(cp949_reverse[0]));

static void write_status(const char *path, const char *body)
{
    FILE *f;
    char temp[1024];
    if (path == NULL || path[0] == '\0') return;
    if (strlen(path) + 5 >= sizeof(temp)) return;
    strcpy(temp, path);
    strcat(temp, ".tmp");
    f = fopen(temp, "wb");
    if (f == NULL) return;
    fputs(body, f);
    fclose(f);
    remove(path);
    rename(temp, path);
}

static void hex_bytes(char *out, const unsigned char *p, unsigned long n)
{
    unsigned long i;
    char one[4];
    out[0] = '\0';
    for (i = 0; i < n && i < 8; ++i) {
        if (i != 0) strcat(out, " ");
        sprintf(one, "%02X", (unsigned int)p[i]);
        strcat(out, one);
    }
}

static int append_scalar(ScalarBuffer *b, U32 scalar)
{
    U32 *next;
    unsigned long cap;
    if (b->count == b->capacity) {
        cap = b->capacity == 0 ? 256UL : b->capacity * 2UL;
        if (cap < b->capacity || cap > MAX_FILE_BYTES) return 0;
        next = (U32 *)realloc(b->items, cap * sizeof(U32));
        if (next == NULL) return 0;
        b->items = next;
        b->capacity = cap;
    }
    b->items[b->count++] = scalar;
    return 1;
}

static int read_binary(const char *path, unsigned char **data, unsigned long *size)
{
    FILE *f;
    unsigned char chunk[CHUNK_SIZE];
    unsigned char *all;
    unsigned long used;
    unsigned long cap;
    size_t got;
    f = fopen(path, "rb");
    if (f == NULL) return ENC_ERR_OPEN_INPUT;
    all = NULL;
    used = 0;
    cap = 0;
    for (;;) {
        got = fread(chunk, 1, sizeof(chunk), f);
        if (got != 0) {
            unsigned char *next;
            unsigned long required;
            required = used + (unsigned long)got;
            if (required < used || required > MAX_FILE_BYTES) {
                free(all);
                fclose(f);
                return ENC_ERR_READ;
            }
            if (required > cap) {
                unsigned long newcap;
                newcap = cap == 0 ? CHUNK_SIZE : cap;
                while (newcap < required) newcap *= 2UL;
                if (newcap > MAX_FILE_BYTES) newcap = MAX_FILE_BYTES;
                next = (unsigned char *)realloc(all, newcap);
                if (next == NULL) {
                    free(all);
                    fclose(f);
                    return ENC_ERR_READ;
                }
                all = next;
                cap = newcap;
            }
            memcpy(all + used, chunk, got);
            used = required;
        }
        if (got < sizeof(chunk)) {
            if (ferror(f)) {
                free(all);
                fclose(f);
                return ENC_ERR_READ;
            }
            break;
        }
    }
    fclose(f);
    *data = all;
    *size = used;
    return ENC_OK;
}

static int cp437_from_unicode(U32 scalar)
{
    unsigned int i;
    for (i = 0; i < 256U; ++i)
        if (cp437_to_unicode[i] == scalar) return (int)i;
    return -1;
}

static int cp949_decode_pair(U16 code, U32 *scalar)
{
    unsigned long lo;
    unsigned long hi;
    unsigned long mid;
    lo = 0;
    hi = cp949_forward_count;
    while (lo < hi) {
        mid = lo + (hi - lo) / 2UL;
        if (cp949_forward[mid].code == code) {
            *scalar = cp949_forward[mid].scalar;
            return 1;
        }
        if (cp949_forward[mid].code < code) lo = mid + 1UL;
        else hi = mid;
    }
    return 0;
}

static int cp949_encode_scalar(U32 scalar, U16 *code)
{
    unsigned long lo;
    unsigned long hi;
    unsigned long mid;
    lo = 0;
    hi = cp949_reverse_count;
    while (lo < hi) {
        mid = lo + (hi - lo) / 2UL;
        if (cp949_reverse[mid].scalar == scalar) {
            *code = cp949_reverse[mid].code;
            return 1;
        }
        if (cp949_reverse[mid].scalar < scalar) lo = mid + 1UL;
        else hi = mid;
    }
    return 0;
}

static int utf8_decode_one(const unsigned char *s, unsigned long n,
                           unsigned long *used, U32 *scalar)
{
    unsigned int a, b, c, d;
    if (n == 0) return 0;
    a = s[0];
    if (a <= 0x7FU) { *used = 1; *scalar = a; return 1; }
    if (a >= 0xC2U && a <= 0xDFU) {
        if (n < 2) return 0;
        b = s[1];
        if ((b & 0xC0U) != 0x80U) return 0;
        *scalar = ((U32)(a & 0x1FU) << 6) | (U32)(b & 0x3FU);
        *used = 2; return 1;
    }
    if (a >= 0xE0U && a <= 0xEFU) {
        if (n < 3) return 0;
        b = s[1]; c = s[2];
        if ((b & 0xC0U) != 0x80U || (c & 0xC0U) != 0x80U) return 0;
        if ((a == 0xE0U && b < 0xA0U) || (a == 0xEDU && b >= 0xA0U)) return 0;
        *scalar = ((U32)(a & 0x0FU) << 12) |
                  ((U32)(b & 0x3FU) << 6) | (U32)(c & 0x3FU);
        *used = 3; return 1;
    }
    if (a >= 0xF0U && a <= 0xF4U) {
        if (n < 4) return 0;
        b = s[1]; c = s[2]; d = s[3];
        if ((b & 0xC0U) != 0x80U || (c & 0xC0U) != 0x80U ||
            (d & 0xC0U) != 0x80U) return 0;
        if ((a == 0xF0U && b < 0x90U) || (a == 0xF4U && b > 0x8FU)) return 0;
        *scalar = ((U32)(a & 7U) << 18) | ((U32)(b & 0x3FU) << 12) |
                  ((U32)(c & 0x3FU) << 6) | (U32)(d & 0x3FU);
        *used = 4; return 1;
    }
    return 0;
}

static void status_error(const char *status, const char *error, unsigned long code,
                         unsigned long offset, const unsigned char *bytes,
                         unsigned long byte_count, U32 scalar, int has_scalar)
{
    char body[512];
    char hex[40];
    hex_bytes(hex, bytes, byte_count);
    if (has_scalar)
        sprintf(body, "ERROR=%s\r\nCODE=%lu\r\nOFFSET=%lu\r\nBYTES=%s\r\nCODEPOINT=U+%08lX\r\n",
                error, code, offset, hex, scalar);
    else
        sprintf(body, "ERROR=%s\r\nCODE=%lu\r\nOFFSET=%lu\r\nBYTES=%s\r\n",
                error, code, offset, hex);
    write_status(status, body);
}

static int decode_input(const unsigned char *data, unsigned long size,
                        const char *encoding, ScalarBuffer *out,
                        const char *status)
{
    unsigned long i, used;
    U32 scalar;
    unsigned int a, b;
    int utf8;
    int utf16;
    int be;
    utf8 = (strcmp(encoding, "UTF-8") == 0 || strcmp(encoding, "UTF-8-BOM") == 0);
    utf16 = (strcmp(encoding, "UTF-16LE") == 0 || strcmp(encoding, "UTF-16LE-BOM") == 0);
    be = (strcmp(encoding, "UTF-16BE") == 0 || strcmp(encoding, "UTF-16BE-BOM") == 0);
    i = 0;
    if (utf8 && size >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF) i = 3;
    if (utf16 && size >= 2 && data[0] == 0xFF && data[1] == 0xFE) i = 2;
    if (be && size >= 2 && data[0] == 0xFE && data[1] == 0xFF) i = 2;
    if ((strcmp(encoding, "UTF-8-BOM") == 0 && i != 3) ||
        (strcmp(encoding, "UTF-16LE-BOM") == 0 && i != 2) ||
        (strcmp(encoding, "UTF-16BE-BOM") == 0 && i != 2)) {
        status_error(status, "BOM_REQUIRED", ENC_ERR_ARGUMENT, 0, data, size < 3 ? size : 3, 0, 0);
        return 0;
    }
    while (i < size) {
        if (utf8) {
            if (utf8_decode_one(data + i, size - i, &used, &scalar)) {
                if (!append_scalar(out, scalar)) return 0;
                i += used;
            } else {
                status_error(status, "INVALID_UTF8", ENC_ERR_INVALID_UTF8, i, data + i,
                             size - i < 4 ? size - i : 4, 0, 0);
                return 0;
            }
        } else if (utf16 || be) {
            if (i + 1 >= size) {
                status_error(status, "INVALID_UTF16", ENC_ERR_INVALID_UTF16, i, data + i, 1, 0, 0);
                return 0;
            }
            a = data[i]; b = data[i + 1];
            scalar = be ? ((U32)a << 8) | b : ((U32)b << 8) | a;
            i += 2;
            if (scalar >= 0xD800U && scalar <= 0xDBFFU) {
                U32 low;
                if (i + 1 >= size) {
                    status_error(status, "INVALID_UTF16", ENC_ERR_INVALID_UTF16, i - 2, data + i - 2, 2, scalar, 1);
                    return 0;
                }
                low = be ? ((U32)data[i] << 8) | data[i + 1] :
                           ((U32)data[i + 1] << 8) | data[i];
                if (low < 0xDC00U || low > 0xDFFFU) {
                    status_error(status, "INVALID_UTF16", ENC_ERR_INVALID_UTF16, i - 2, data + i - 2, 4, scalar, 1);
                    return 0;
                }
                scalar = 0x10000UL + ((scalar - 0xD800UL) << 10) + (low - 0xDC00UL);
                i += 2;
            } else if (scalar >= 0xDC00U && scalar <= 0xDFFFU) {
                status_error(status, "INVALID_UTF16", ENC_ERR_INVALID_UTF16, i - 2, data + i - 2, 2, scalar, 1);
                return 0;
            }
            if (!append_scalar(out, scalar)) return 0;
        } else if (strcmp(encoding, "CP437") == 0) {
            if (!append_scalar(out, cp437_to_unicode[data[i++]])) return 0;
        } else if (strcmp(encoding, "CP1252") == 0) {
            scalar = cp1252_to_unicode[data[i]];
            if (scalar == 0xFFFFFFFFUL) {
                status_error(status, "INVALID_CP1252", ENC_ERR_ARGUMENT, i, data + i, 1, 0, 0);
                return 0;
            }
            if (!append_scalar(out, scalar)) return 0;
            ++i;
        } else if (strcmp(encoding, "CP949") == 0) {
            if (data[i] < 0x80U) {
                if (!append_scalar(out, data[i++])) return 0;
            } else if (i + 1 < size && cp949_decode_pair((U16)(((unsigned int)data[i] << 8) | data[i + 1]), &scalar)) {
                if (!append_scalar(out, scalar)) return 0;
                i += 2;
            } else {
                status_error(status, "INVALID_CP949", ENC_ERR_INVALID_CP949, i, data + i,
                             i + 1 < size ? 2 : 1, 0, 0);
                return 0;
            }
        } else {
            return 0;
        }
    }
    return 1;
}

static int append_utf8(unsigned char **out, unsigned long *used, unsigned long *cap, U32 c)
{
    unsigned char b[4];
    unsigned long n;
    if (c <= 0x7FUL) { b[0] = (unsigned char)c; n = 1; }
    else if (c <= 0x7FFUL) {
        b[0] = (unsigned char)(0xC0U | (c >> 6));
        b[1] = (unsigned char)(0x80U | (c & 0x3FU)); n = 2;
    } else if (c <= 0xFFFFUL && !(c >= 0xD800UL && c <= 0xDFFFUL)) {
        b[0] = (unsigned char)(0xE0U | (c >> 12));
        b[1] = (unsigned char)(0x80U | ((c >> 6) & 0x3FU));
        b[2] = (unsigned char)(0x80U | (c & 0x3FU)); n = 3;
    } else if (c <= 0x10FFFFUL) {
        b[0] = (unsigned char)(0xF0U | (c >> 18));
        b[1] = (unsigned char)(0x80U | ((c >> 12) & 0x3FU));
        b[2] = (unsigned char)(0x80U | ((c >> 6) & 0x3FU));
        b[3] = (unsigned char)(0x80U | (c & 0x3FU)); n = 4;
    } else return 0;
    if (*used + n > *cap) {
        unsigned long nc = *cap == 0 ? CHUNK_SIZE : *cap * 2UL;
        unsigned char *next;
        while (nc < *used + n) nc *= 2UL;
        next = (unsigned char *)realloc(*out, nc);
        if (next == NULL) return 0;
        *out = next; *cap = nc;
    }
    memcpy(*out + *used, b, n); *used += n;
    return 1;
}

static int encode_output(const ScalarBuffer *text, const char *encoding,
                        unsigned char **out, unsigned long *out_size,
                        const char *status)
{
    unsigned long i, used, cap;
    U32 c;
    U16 code;
    unsigned char *buf;
    int utf8, utf16, be;
    utf8 = (strcmp(encoding, "UTF-8") == 0 || strcmp(encoding, "UTF-8-BOM") == 0);
    utf16 = (strcmp(encoding, "UTF-16LE") == 0 || strcmp(encoding, "UTF-16LE-BOM") == 0);
    be = (strcmp(encoding, "UTF-16BE") == 0 || strcmp(encoding, "UTF-16BE-BOM") == 0);
    cap = CHUNK_SIZE; used = 0; buf = (unsigned char *)malloc(cap);
    if (buf == NULL) return 0;
    if (strcmp(encoding, "UTF-8-BOM") == 0) {
        buf[used++] = 0xEF; buf[used++] = 0xBB; buf[used++] = 0xBF;
    } else if (strcmp(encoding, "UTF-16LE-BOM") == 0) {
        buf[used++] = 0xFF; buf[used++] = 0xFE;
    } else if (strcmp(encoding, "UTF-16BE-BOM") == 0) {
        buf[used++] = 0xFE; buf[used++] = 0xFF;
    }
    for (i = 0; i < text->count; ++i) {
        c = text->items[i];
        if (utf8) {
            if (!append_utf8(&buf, &used, &cap, c)) { free(buf); return 0; }
        } else if (utf16 || be) {
            if (c < 0x10000UL) {
                if (used + 2 > cap) {
                    unsigned char *next = (unsigned char *)realloc(buf, cap * 2UL);
                    if (next == NULL) { free(buf); return 0; }
                    buf = next; cap *= 2UL;
                }
                if (be) { buf[used++] = (unsigned char)(c >> 8); buf[used++] = (unsigned char)c; }
                else { buf[used++] = (unsigned char)c; buf[used++] = (unsigned char)(c >> 8); }
            } else {
                U32 v = c - 0x10000UL;
                U16 hi = (U16)(0xD800U + (v >> 10));
                U16 lo = (U16)(0xDC00U + (v & 0x3FFU));
                if (used + 4 > cap) {
                    unsigned char *next = (unsigned char *)realloc(buf, cap * 2UL);
                    if (next == NULL) { free(buf); return 0; }
                    buf = next; cap *= 2UL;
                }
                if (be) {
                    buf[used++] = (unsigned char)(hi >> 8); buf[used++] = (unsigned char)hi;
                    buf[used++] = (unsigned char)(lo >> 8); buf[used++] = (unsigned char)lo;
                } else {
                    buf[used++] = (unsigned char)hi; buf[used++] = (unsigned char)(hi >> 8);
                    buf[used++] = (unsigned char)lo; buf[used++] = (unsigned char)(lo >> 8);
                }
            }
        } else if (strcmp(encoding, "CP437") == 0 || strcmp(encoding, "CP1252") == 0) {
            int found = -1;
            unsigned int j;
            const U32 *map = strcmp(encoding, "CP437") == 0 ? cp437_to_unicode : cp1252_to_unicode;
            for (j = 0; j < 256U; ++j) if (map[j] == c) { found = (int)j; break; }
            if (found < 0) {
                status_error(status, "UNREPRESENTABLE", ENC_ERR_UNREPRESENTABLE, i, NULL, 0, c, 1);
                free(buf); return 0;
            }
            if (used == cap) {
                unsigned char *next = (unsigned char *)realloc(buf, cap * 2UL);
                if (next == NULL) { free(buf); return 0; }
                buf = next; cap *= 2UL;
            }
            buf[used++] = (unsigned char)found;
        } else if (strcmp(encoding, "CP949") == 0) {
            if (c < 0x80UL) code = (U16)c;
            else if (!cp949_encode_scalar(c, &code)) {
                status_error(status, "UNREPRESENTABLE", ENC_ERR_UNREPRESENTABLE, i, NULL, 0, c, 1);
                free(buf); return 0;
            }
            if (code <= 0xFFU) {
                if (used == cap) { unsigned char *next = (unsigned char *)realloc(buf, cap * 2UL); if (!next) { free(buf); return 0; } buf=next; cap*=2UL; }
                buf[used++] = (unsigned char)code;
            } else {
                if (used + 2 > cap) { unsigned char *next = (unsigned char *)realloc(buf, cap * 2UL); if (!next) { free(buf); return 0; } buf=next; cap*=2UL; }
                buf[used++] = (unsigned char)(code >> 8); buf[used++] = (unsigned char)code;
            }
        } else { free(buf); return 0; }
    }
    *out = buf; *out_size = used;
    return 1;
}

static int write_output(const char *path, const unsigned char *data, unsigned long size)
{
    char temp[1024];
    FILE *f;
    size_t wrote;
    if (strlen(path) + 5 >= sizeof(temp)) return ENC_ERR_OPEN_OUTPUT;
    strcpy(temp, path); strcat(temp, ".tmp");
    f = fopen(temp, "wb");
    if (f == NULL) return ENC_ERR_OPEN_OUTPUT;
    wrote = fwrite(data, 1, size, f);
    {
        int close_result;
        close_result = fclose(f);
        if (wrote != size || close_result != 0) {
        remove(temp); return ENC_ERR_WRITE;
        }
    }
    if (rename(temp, path) != 0) {
        remove(temp); return ENC_ERR_WRITE;
    }
    return ENC_OK;
}

static const char *option_value(int argc, char **argv, const char *name)
{
    int i;
    for (i = 1; i + 1 < argc; ++i)
        if (strcmp(argv[i], name) == 0) return argv[i + 1];
    return NULL;
}

static int self_test(void)
{
    unsigned int i;
    unsigned int j;
    U32 scalar;
    U16 code;
    unsigned long used;
    unsigned long consumed;
    unsigned char *utf8;
    unsigned long utf8_capacity;
    unsigned char sample[] = { 0x41, 0xC2, 0xA2, 0xE2, 0x82, 0xAC, 0xF0, 0x9F, 0x98, 0x80 };
    unsigned char malformed1[] = { 0xC0, 0xAF };
    unsigned char malformed2[] = { 0xE2, 0x28, 0xA1 };
    unsigned char malformed3[] = { 0xF0, 0x9F, 0x98 };
    unsigned char *utf16;
    unsigned long utf16_size;
    ScalarBuffer original;
    ScalarBuffer roundtrip;
    ScalarBuffer glyphs;
    ScalarBuffer recovered;
    ScalarBuffer korean;
    unsigned char raw_cp949[8];
    unsigned long raw_count;
    unsigned char *utf8_recovery;
    unsigned long utf8_recovery_size;
    unsigned long utf8_recovery_capacity;
    unsigned char *recovered_raw;
    unsigned long chunk_size;
    unsigned char *chunk_fixture;

    for (i = 0; i < 256U; ++i) {
        if (cp437_from_unicode(cp437_to_unicode[i]) != (int)i) return 1;
    }
    if (cp437_from_unicode(0x255FUL) != 0xC7) return 2;
    if (cp437_from_unicode(0x2551UL) != 0xBA) return 3;
    if (cp437_from_unicode(0x2564UL) != 0xD1) return 39;
    if (cp437_from_unicode(0x2591UL) != 0xB0) return 4;
    if (cp437_from_unicode(0x2588UL) != 0xDB) return 5;

    {
        ScalarBuffer cp1252_text;
        ScalarBuffer cp1252_decoded;
        unsigned char cp1252_input[256];
        unsigned long cp1252_count;
        unsigned char *cp1252_bytes;
        unsigned long cp1252_size;
        cp1252_text.items = NULL; cp1252_text.count = 0; cp1252_text.capacity = 0;
        cp1252_decoded.items = NULL; cp1252_decoded.count = 0; cp1252_decoded.capacity = 0;
        cp1252_count = 0;
        for (i = 0; i < 256U; ++i) {
            if (cp1252_to_unicode[i] == 0xFFFFFFFFUL) continue;
            for (j = 0; j < 256U; ++j)
                if (cp1252_to_unicode[j] == cp1252_to_unicode[i]) break;
            if (j != i) { free(cp1252_text.items); return 6; }
            cp1252_input[cp1252_count++] = (unsigned char)i;
            if (!append_scalar(&cp1252_text, cp1252_to_unicode[i])) {
                free(cp1252_text.items); return 6;
            }
        }
        if (!decode_input(cp1252_input, cp1252_count, "CP1252", &cp1252_decoded, NULL)) {
            free(cp1252_text.items); free(cp1252_decoded.items); return 6;
        }
        if (cp1252_decoded.count != cp1252_text.count) {
            free(cp1252_text.items); free(cp1252_decoded.items); return 6;
        }
        for (i = 0; i < cp1252_text.count; ++i) {
            if (cp1252_decoded.items[i] != cp1252_text.items[i]) {
                free(cp1252_text.items); free(cp1252_decoded.items); return 6;
            }
        }
        cp1252_bytes = NULL; cp1252_size = 0;
        if (!encode_output(&cp1252_text, "CP1252", &cp1252_bytes, &cp1252_size, NULL)) {
            free(cp1252_text.items); free(cp1252_decoded.items); return 6;
        }
        if (cp1252_size != cp1252_count) {
            free(cp1252_text.items); free(cp1252_decoded.items); free(cp1252_bytes); return 6;
        }
        for (i = 0; i < cp1252_count; ++i) {
            if (cp1252_bytes[i] != cp1252_input[i]) {
                free(cp1252_text.items); free(cp1252_decoded.items); free(cp1252_bytes); return 6;
            }
        }
        free(cp1252_text.items); free(cp1252_decoded.items); free(cp1252_bytes);
    }

    for (i = 0; i < cp949_forward_count; ++i) {
        if (!cp949_decode_pair(cp949_forward[i].code, &scalar)) return 7;
        if (scalar != cp949_forward[i].scalar) return 8;
        if (!cp949_encode_scalar(scalar, &code)) return 9;
        if (code != cp949_forward[i].code) return 10;
    }

    original.items = NULL; original.count = 0; original.capacity = 0;
    roundtrip.items = NULL; roundtrip.count = 0; roundtrip.capacity = 0;
    for (i = 0; i < sizeof(sample); ) {
        if (!utf8_decode_one(sample + i, sizeof(sample) - i, &consumed, &scalar)) return 11;
        if (!append_scalar(&original, scalar)) return 12;
        i += (unsigned int)consumed;
    }
    if (original.count != 4UL || original.items[0] != 0x41UL ||
        original.items[1] != 0xA2UL || original.items[2] != 0x20ACUL ||
        original.items[3] != 0x1F600UL) return 13;
    utf8 = NULL; used = 0; utf8_capacity = 0;
    for (i = 0; i < original.count; ++i)
        if (!append_utf8(&utf8, &used, &utf8_capacity, original.items[i])) return 14;
    if (used != sizeof(sample) || memcmp(utf8, sample, sizeof(sample)) != 0) {
        free(utf8); free(original.items); return 15;
    }
    free(utf8);
    if (utf8_decode_one(malformed1, sizeof(malformed1), &consumed, &scalar)) return 16;
    if (utf8_decode_one(malformed2, sizeof(malformed2), &consumed, &scalar)) return 17;
    if (utf8_decode_one(malformed3, sizeof(malformed3), &consumed, &scalar)) return 18;

    if (!utf8_decode_one(sample + 1, 2, &consumed, &scalar) ||
        consumed != 2 || scalar != 0xA2UL) { free(original.items); return 19; }

    roundtrip.items = NULL; roundtrip.count = 0; roundtrip.capacity = 0;
    if (!decode_input(sample, sizeof(sample), "UTF-8", &roundtrip, NULL)) {
        free(original.items); free(roundtrip.items); return 20;
    }
    if (roundtrip.count != original.count) { free(original.items); free(roundtrip.items); return 21; }
    for (i = 0; i < original.count; ++i)
        if (roundtrip.items[i] != original.items[i]) { free(original.items); free(roundtrip.items); return 22; }
    free(roundtrip.items);

    utf16 = NULL; utf16_size = 0;
    if (!encode_output(&original, "UTF-16LE", &utf16, &utf16_size, NULL)) {
        free(original.items); return 23;
    }
    roundtrip.items = NULL; roundtrip.count = 0; roundtrip.capacity = 0;
    if (!decode_input(utf16, utf16_size, "UTF-16LE", &roundtrip, NULL)) {
        free(utf16); free(original.items); free(roundtrip.items); return 24;
    }
    if (roundtrip.count != original.count) { free(utf16); free(original.items); free(roundtrip.items); return 25; }
    for (i = 0; i < original.count; ++i)
        if (roundtrip.items[i] != original.items[i]) { free(utf16); free(original.items); free(roundtrip.items); return 26; }
    free(utf16); free(roundtrip.items); free(original.items);

    /* Recreate CP949 bytes as CP437 glyphs, UTF-8 serialize, and recover. */
    korean.items = NULL; korean.count = 0; korean.capacity = 0;
    if (!append_scalar(&korean, 0xD55Cul) || !append_scalar(&korean, 0xAE00ul)) return 27;
    raw_count = 0;
    for (i = 0; i < korean.count; ++i) {
        if (!cp949_encode_scalar(korean.items[i], &code)) { free(korean.items); return 28; }
        raw_cp949[raw_count++] = (unsigned char)(code >> 8);
        raw_cp949[raw_count++] = (unsigned char)code;
    }
    glyphs.items = NULL; glyphs.count = 0; glyphs.capacity = 0;
    for (i = 0; i < raw_count; ++i)
        if (!append_scalar(&glyphs, cp437_to_unicode[raw_cp949[i]])) { free(korean.items); free(glyphs.items); return 29; }
    utf8_recovery = NULL; utf8_recovery_size = 0; utf8_recovery_capacity = 0;
    for (i = 0; i < glyphs.count; ++i)
        if (!append_utf8(&utf8_recovery, &utf8_recovery_size, &utf8_recovery_capacity, glyphs.items[i])) {
            free(korean.items); free(glyphs.items); free(utf8_recovery); return 30;
        }
    roundtrip.items = NULL; roundtrip.count = 0; roundtrip.capacity = 0;
    if (!decode_input(utf8_recovery, utf8_recovery_size, "UTF-8", &roundtrip, NULL)) {
        free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items); return 31;
    }
    recovered_raw = (unsigned char *)malloc(roundtrip.count == 0 ? 1UL : roundtrip.count);
    if (recovered_raw == NULL) { free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items); return 32; }
    for (i = 0; i < roundtrip.count; ++i) {
        int value;
        value = cp437_from_unicode(roundtrip.items[i]);
        if (value < 0) { free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items); free(recovered_raw); return 33; }
        recovered_raw[i] = (unsigned char)value;
    }
    recovered.items = NULL; recovered.count = 0; recovered.capacity = 0;
    if (!decode_input(recovered_raw, roundtrip.count, "CP949", &recovered, NULL)) {
        free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items); free(recovered_raw); free(recovered.items); return 34;
    }
    if (recovered.count != korean.count || recovered.items[0] != korean.items[0] ||
        recovered.items[1] != korean.items[1]) {
        free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items); free(recovered_raw); free(recovered.items); return 35;
    }
    free(korean.items); free(glyphs.items); free(utf8_recovery); free(roundtrip.items);
    free(recovered_raw); free(recovered.items);

    /* A four-byte UTF-8 scalar straddling a 32 KiB read boundary. */
    chunk_size = CHUNK_SIZE + 3UL;
    chunk_fixture = (unsigned char *)malloc(chunk_size);
    if (chunk_fixture == NULL) return 36;
    memset(chunk_fixture, 0x41, chunk_size);
    chunk_fixture[CHUNK_SIZE - 2UL] = 0xF0;
    chunk_fixture[CHUNK_SIZE - 1UL] = 0x9F;
    chunk_fixture[CHUNK_SIZE] = 0x98;
    chunk_fixture[CHUNK_SIZE + 1UL] = 0x80;
    if (!utf8_decode_one(chunk_fixture + CHUNK_SIZE - 2UL, 4UL, &consumed, &scalar) ||
        consumed != 4UL || scalar != 0x1F600UL) { free(chunk_fixture); return 37; }
    roundtrip.items = NULL; roundtrip.count = 0; roundtrip.capacity = 0;
    if (!decode_input(chunk_fixture, chunk_size, "UTF-8", &roundtrip, NULL) ||
        roundtrip.count != CHUNK_SIZE || roundtrip.items[CHUNK_SIZE - 2UL] != 0x1F600UL) {
        free(chunk_fixture); free(roundtrip.items); return 38;
    }
    free(roundtrip.items); free(chunk_fixture);

    puts("OK");
    return 0;
}
int main(int argc, char **argv)
{
    const char *in_path, *out_path, *in_enc, *out_enc, *status;
    const char *mode, *mis, *real;
    unsigned char *input, *output;
    unsigned long input_size, output_size, i;
    ScalarBuffer decoded, recovered;
    int rc;
    if (argc == 2 && strcmp(argv[1], "/test") == 0) return self_test();
    in_path = option_value(argc, argv, "/in");
    out_path = option_value(argc, argv, "/out");
    in_enc = option_value(argc, argv, "/input");
    out_enc = option_value(argc, argv, "/output");
    status = option_value(argc, argv, "/status");
    mode = option_value(argc, argv, "/mode");
    mis = option_value(argc, argv, "/misinterpret");
    real = option_value(argc, argv, "/real");
    if (in_path == NULL || out_path == NULL || in_enc == NULL || out_enc == NULL || status == NULL) {
        puts("Usage: EncodingTool /in path /out path /input encoding /output encoding /status file [/mode recovery /misinterpret CP437 /real CP949]");
        return ENC_ERR_ARGUMENT;
    }
    if (strcmp(in_path, out_path) == 0) {
        write_status(status, "ERROR=SAME_PATH\r\nCODE=1\r\n");
        return ENC_ERR_ARGUMENT;
    }
    input = NULL; input_size = 0;
    rc = read_binary(in_path, &input, &input_size);
    if (rc != ENC_OK) {
        write_status(status, "ERROR=OPEN_OR_READ_INPUT\r\n");
        return rc;
    }
    decoded.items = NULL; decoded.count = 0; decoded.capacity = 0;
    recovered.items = NULL; recovered.count = 0; recovered.capacity = 0;
    if (!decode_input(input, input_size, in_enc, &decoded, status)) {
        free(input); free(decoded.items); return ENC_ERR_INVALID_UTF8;
    }
    if (mode != NULL && strcmp(mode, "recovery") == 0) {
        if (mis == NULL || real == NULL || strcmp(mis, "CP437") != 0 || strcmp(real, "CP949") != 0) {
            write_status(status, "ERROR=CP437_RECOVERY_OPTIONS\r\nCODE=14\r\n");
            free(input); free(decoded.items); return ENC_ERR_ARGUMENT;
        }
        for (i = 0; i < decoded.count; ++i) {
            int byte_value;
            if (decoded.items[i] == 0xFFFDU) {
                status_error(status, "CP437_REVERSE", ENC_ERR_CP437_REVERSE, i, NULL, 0, decoded.items[i], 1);
                free(input); free(decoded.items); return ENC_ERR_CP437_REVERSE;
            }
            byte_value = cp437_from_unicode(decoded.items[i]);
            if (byte_value < 0) {
                status_error(status, "CP437_REVERSE", ENC_ERR_CP437_REVERSE, i, NULL, 0, decoded.items[i], 1);
                free(input); free(decoded.items); return ENC_ERR_CP437_REVERSE;
            }
            if (!append_scalar(&recovered, (U32)byte_value)) {
                free(input); free(decoded.items); return ENC_ERR_READ;
            }
        }
        /* Reinterpret recovered scalar values as original raw bytes, then CP949 decode. */
        {
            unsigned char *raw;
            ScalarBuffer actual;
            raw = (unsigned char *)malloc(recovered.count == 0 ? 1 : recovered.count);
            if (raw == NULL) { free(input); free(decoded.items); free(recovered.items); return ENC_ERR_READ; }
            for (i = 0; i < recovered.count; ++i) raw[i] = (unsigned char)recovered.items[i];
            actual.items = NULL; actual.count = 0; actual.capacity = 0;
            if (!decode_input(raw, recovered.count, real, &actual, status)) {
                free(raw); free(input); free(decoded.items); free(recovered.items); free(actual.items);
                return ENC_ERR_INVALID_CP949;
            }
            free(raw); free(decoded.items); free(recovered.items);
            decoded = actual;
        }
    }
    output = NULL; output_size = 0;
    if (!encode_output(&decoded, out_enc, &output, &output_size, status)) {
        free(input); free(decoded.items); free(output); return ENC_ERR_UNREPRESENTABLE;
    }
    rc = write_output(out_path, output, output_size);
    if (rc == ENC_OK) write_status(status, "OK\r\nCODE=0\r\n");
    else write_status(status, "ERROR=WRITE_OUTPUT\r\nCODE=5\r\n");
    free(input); free(decoded.items); free(output);
    return rc;
}
